def _smo(self, res_kp_seq, s, e):
    if self.smo_k_d <= 1:
        return res_kp_seq
    new_res_kp_seq = res_kp_seq.copy()
    n = res_kp_seq.shape[1]
    half_k = self.smo_k_d // 2
    for i in range(s, e):
        ss = max(0, i - half_k)
        ee = min(n, i + half_k + 1)
        res_kp_seq[:, i, :202] = np.mean(new_res_kp_seq[:, ss:ee, :202], axis=1)
    return res_kp_seq

